var glyphs sync.Map                               // string -> *Glyph

func GlyphFor(name string) *Glyph {
    if g, ok := glyphs.Load(name); ok { return g.(*Glyph) }
    g := &Glyph{Name: name, W: 8, H: 12}
    actual, _ := glyphs.LoadOrStore(name, g)      // race-safe canonical
    return actual.(*Glyph)
}
